/* =========================================
   VÝBĚR PŘEDMĚTU A TÉMATU
========================================= */

const subjectSelect = document.getElementById("subjectSelect");
const topicSelect = document.getElementById("topicSelect");
const startTestButton = document.getElementById("startTest");
const testContainer = document.getElementById("testContainer");

// Změna předmětu
if (subjectSelect && topicSelect && startTestButton && testContainer) {
    subjectSelect.addEventListener("change", function () {
        const subject = subjectSelect.value;

        topicSelect.innerHTML =
            '<option value="">Vyber téma</option>';

        topicSelect.disabled = true;
        startTestButton.disabled = true;
        testContainer.innerHTML = "";

        if (!subject || !testDatabase[subject]) {
            topicSelect.innerHTML =
                '<option value="">Nejprve vyber předmět</option>';
            return;
        }

        const topics = testDatabase[subject];

        for (const [topicId, topic] of Object.entries(topics)) {
            const option = document.createElement("option");

            option.value = topicId;
            option.textContent = topic.name;

            topicSelect.appendChild(option);
        }

        topicSelect.disabled = false;
    });

    // Změna tématu
    topicSelect.addEventListener("change", function () {
        startTestButton.disabled = !topicSelect.value;
        testContainer.innerHTML = "";
    });

    // Spuštění testu
    startTestButton.addEventListener("click", function () {
        const subject = subjectSelect.value;
        const topic = topicSelect.value;

        const selectedTest = testDatabase[subject]?.[topic];

        if (!selectedTest) {
            return;
        }

        showTest(selectedTest);
    });
}

// Náhodně promíchá prvky pole, aniž by změnila původní pole.
function shuffleArray(array) {
    const shuffled = [...array];
    
    for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    
    return shuffled;
}

/* =========================================
   ZOBRAZENÍ TESTU
===========================================*/

function showTest(test) {
    testContainer.innerHTML = "";
    
    // Promíchání otázek a odpovědí.
    // U každé odpovědi si ponecháme její původní index,
    // abychom mohli správně určit správnou odpověď.
    const shuffledTest = {
        ...test,
        questions: shuffleArray(test.questions).map(q => {
            const shuffledAnswers = shuffleArray(
                q.answers.map((answer, originalIndex) => ({
                    answer,
                    originalIndex
                }))
            );
            
            return {
                ...q,
                answers: shuffledAnswers.map(a => a.answer),
                correct: shuffledAnswers.findIndex(
                    a => a.originalIndex === q.correct
                )
            };
        })
    };
    
    const heading = document.createElement("h3");
    heading.textContent = shuffledTest.name;
    testContainer.appendChild(heading);
    
    shuffledTest.questions.forEach((q, index) => {
        const questionElement = document.createElement("div");
        questionElement.className = "question";
        
        const title = document.createElement("h4");
        title.textContent = `${index + 1}. ${q.question}`;
        questionElement.appendChild(title);
        
        q.answers.forEach((answer, answerIndex) => {
            const label = document.createElement("label");
            label.className = "answer";
            
            const input = document.createElement("input");
            input.type = "radio";
            input.name = `question-${index}`;
            input.value = answerIndex;
            
            label.appendChild(input);
            label.appendChild(
                document.createTextNode(" " + answer)
            );
            
            questionElement.appendChild(label);
        });
        
        testContainer.appendChild(questionElement);
    });
    
    const submitButton = document.createElement("button");
    submitButton.textContent = "Vyhodnotit test";
    submitButton.type = "button";
    submitButton.style.marginTop = "20px";
    
    submitButton.addEventListener("click", function() {
        checkTestAnswers(shuffledTest);
    });
    
    testContainer.appendChild(submitButton);
}

/* =========================================
   VYHODNOCENÍ TESTU
========================================= */

function checkTestAnswers(test) {
    let score = 0;
    let unanswered = 0;
    
    test.questions.forEach((q, index) => {
        const selected = testContainer.querySelector(
            `input[name="question-${index}"]:checked`
        );
        
        if (!selected) {
            unanswered++;
        } else if (Number(selected.value) === q.correct) {
            score++;
        }
    });
    
    if (unanswered > 0) {
        alert(`Nezodpověděl jsi ještě ${unanswered} otázek.`);
        return;
    }
    
    const percentage = Math.round(
        (score / test.questions.length) * 100
    );
    
    let grade;
    
    if (percentage >= 90) {
        grade = "Výborně!";
    } else if (percentage >= 75) {
        grade = "Velmi dobře!";
    } else if (percentage >= 60) {
        grade = "Dobrá práce!";
    } else if (percentage >= 40) {
        grade = "Ještě to trochu procvič.";
    } else {
        grade = "Zkus si látku znovu projít.";
    }
    
    const escapeHtml = value => String(value).replace(/[&<>\"']/g, char => ({
        "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;"
    }[char]));
    const reviewHtml = test.questions.map((q, index) => {
        const selected = testContainer.querySelector(`input[name="question-${index}"]:checked`);
        const correctAnswer = q.answers[q.correct];
        const wasCorrect = selected && Number(selected.value) === q.correct;
        return `<li><strong>${index + 1}. ${escapeHtml(q.question)}</strong>
            <p>${wasCorrect ? "Správně." : "Správná odpověď: " + escapeHtml(correctAnswer)}</p>
            <p>${escapeHtml(q.explanation || "")}</p></li>`;
    }).join("");

    testContainer.innerHTML = `
        <div class="test-result">
            <h3>Výsledek: ${escapeHtml(test.name)}</h3>
            <p>${grade}</p>
            <p>Správně: ${score} z ${test.questions.length}</p>
            <p>Úspěšnost: ${percentage} %</p>
            <button id="retryTest" type="button">Opakovat test</button>
            <details class="answer-review" open>
                <summary>Projít otázky a vysvětlení</summary>
                <ol>${reviewHtml}</ol>
            </details>
        </div>
    `;

    document.getElementById("retryTest").addEventListener(
        "click",
        function() {
            showTest(test);
        }
    );
}

/* =========================================
   PŘEPÍNÁNÍ SVĚTLÉHO A TMAVÉHO REŽIMU
========================================= */

const themeToggleBtn = document.getElementById("darkmode-toggle");
const themeCSS = document.getElementById("themeCSS");

if (themeToggleBtn && themeCSS) {
    const savedTheme = localStorage.getItem("theme") || "light";

    themeCSS.href =
        savedTheme === "dark" ? "dark.css" : "style.css";

    themeToggleBtn.checked = savedTheme === "dark";

    themeToggleBtn.addEventListener("change", function () {
        const theme = themeToggleBtn.checked ? "dark" : "light";

        themeCSS.href =
            theme === "dark" ? "dark.css" : "style.css";

        localStorage.setItem("theme", theme);
    });
}

/* =========================================
   ROZBALOVÁNÍ NAVIGACE
========================================= */

const navbar = document.getElementById("navbar");
const toggleBtn = document.getElementById("toggleBtn");

if (navbar && toggleBtn) {
    toggleBtn.addEventListener("click", function () {
        navbar.classList.toggle("collapsed");

        const isCollapsed =
            navbar.classList.contains("collapsed");

        toggleBtn.setAttribute(
            "aria-label",
            isCollapsed
                ? "Rozšířit navigaci"
                : "Zmenšit navigaci"
        );
    });
}


